import sys
from collections import deque

def simulate(initial_deck):
    deck = deque(initial_deck)
    step = 1

    while deck:
        # Move 'step' cards to the back
        for _ in range(step):
            if not deck:
                return -1
            card = deck.popleft()
            deck.append(card)

        if not deck:
            return -1

        # Take the next card (should be 1, 2, 3, ...)
        card = deck.popleft()
        expected = (len(deck) + 2) // 2

        if card != expected:
            return -1

        step += 1

    return 0

def find_arrangement(n):
    if n == 1:
        return [1]

    # Try all permutations
    from itertools import permutations

    for perm in permutations(range(1, n + 1)):
        if simulate(list(perm)) == 0:
            return list(perm)

    return -1

def solve():
    n = int(sys.stdin.readline().strip())
    result = find_arrangement(n)

    if result == -1:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
